        <div className="product-list">
            <h3>Product List</h3>
            <input type="" className='search-product-box' placeholder='Search Product'
                onChange={searchHandle}
            />
            <ul>
                <li>Name</li>
                <li>Address</li>
            </ul>
            {
                products.length > 0 ? products.map((item, index) =>
                    <ul key={item._id}>
                        <li>{index + 1}</li>
                        <li>{item.name}</li>
                        <li>{item.price}</li>
                        <li>{item.category}</li>
                       

                    </ul>
                )
                    : <h1>No Result Found</h1>
            }
        </div>
    );
}
